<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{AcademicRepository,EmployeeRepository,PakistanErpRepository,SettingsRepository};use App\Support\{Flash,UploadPolicy};
final class NotesController extends AdminPageController{private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():PakistanErpRepository{return new PakistanErpRepository($this->app->database());}public function index(Request$q):Response{return$this->view('notes/index',['pageTitle'=>'Class Notes','activeMenu'=>'homework','activeSubmenu'=>'notes','institute'=>(new SettingsRepository($this->app->database()))->institute(),'notes'=>$this->r()->notes($this->i(),(int)$q->query('class',0),(int)$q->query('subject',0)),'classes'=>(new AcademicRepository($this->app->database()))->withSubjects($this->i()),'teachers'=>(new EmployeeRepository($this->app->database()))->all($this->i(),'',true)]);}public function store(Request$q):Response{$file=$q->file('attachment');$path=null;if($file&&($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$policy=new UploadPolicy(['application/pdf','image/jpeg','image/png','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'],['pdf','jpg','jpeg','png','doc','docx'],5242880);if(!$policy->validate($file)){Flash::add('error','Use a PDF, image, DOC or DOCX up to 5MB.');return Response::redirect(url('/admin/notes'));}$dir=BASE_PATH.'/storage/uploads/notes';if(!is_dir($dir))mkdir($dir,0770,true);$name=$policy->safeFilename(pathinfo((string)$file['name'],PATHINFO_EXTENSION));if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new \RuntimeException('Upload failed.');$path='storage/uploads/notes/'.$name;}$this->r()->saveNote($this->i(),['class_id'=>(int)$q->input('class_id'),'subject_id'=>(int)$q->input('subject_id'),'teacher_id'=>(int)$q->input('teacher_id')?:null,'chapter'=>trim((string)$q->input('chapter'))?:null,'title'=>trim((string)$q->input('title')),'description'=>trim((string)$q->input('description'))?:null,'attachment_path'=>$path,'publish_date'=>(string)$q->input('publish_date'),'status'=>(string)$q->input('status'),'created_by'=>(int)user()['id']]);Flash::add('success','Class note saved.');return Response::redirect(url('/admin/notes'));}public function delete(Request$q):Response{$path=$this->r()->deleteNote((int)$q->route('id'),$this->i());if($path&&is_file(BASE_PATH.'/'.$path))unlink(BASE_PATH.'/'.$path);return Response::redirect(url('/admin/notes'));}}
